import {IDS,PRESIDENCIES,REGIONS,LAW_NAMES,clone,decode} from './model.js';
import {SCENARIOS} from './scenarios.js';
import {TILES,shuffled,exposedRegion,createEventStack} from './event-stack.js';
import {legalElephants,EVENTS,orderLabel} from './actions.js';
import {STORM_FACES,STORM_RESULTS,phaseFor} from './india-phase.js';
import {workspaceKeys} from './workspace-mode.js';
import {debugState,validateDebugState,debugEditRegion,debugEditElephant,debugPhase,debugFlags,debugDeck,debugMoveTile,debugStageEvent,debugResult} from './debug-state.js';

export function createDebugTools({getState,getPayload,apply,restore,showDialog,esc,actions,deploy,draw,hasPending,notify,selectRegion}){
 const $=id=>document.getElementById(id),keys=workspaceKeys('/debug.html');let selected='delhi',controlsOpen=true;
 const label=id=>REGIONS[id].name;
 const pick=(id,title,items,value)=>`<label>${esc(title)}<select id="${id}">${items.map(([v,t,disabled])=>`<option value="${esc(v)}" ${v===value?'selected':''} ${disabled?'disabled':''}>${esc(t)}</option>`).join('')}</select></label>`;
 const number=(id,title,value,min=0,max=20)=>`<label>${title}<input type="number" id="${id}" value="${value}" min="${min}" max="${max}"></label>`;
 const regions=IDS.map(id=>[id,label(id)]),tileLabel=id=>`${label(TILES[id].region)} · ${EVENTS[TILES[id].event]}${TILES[id].modifier!==undefined?' '+(TILES[id].modifier>=0?'+':'')+TILES[id].modifier:''}`;
 function fail(e){if($('form-error')&&$('dialog').open)$('form-error').textContent=e.message;else showDialog('Debug setup unavailable',`<p>${esc(e.message)}</p>`);}
 function guard(){if(hasPending()||getState().eventStack?.pending)throw Error('Finish the pending test, or restore its starting point, before editing this setup.');}
 function commit(next,title){guard();apply(debugResult(getState(),next,title));}
 function form(title,body,confirm,run){showDialog(title,body,`<button id="debug-confirm" class="primary">${confirm}</button>`);$('debug-confirm').onclick=()=>{try{run();}catch(e){fail(e);}};}
 function perform(fn){try{guard();fn();}catch(e){showDialog('Debug setup unavailable',`<p>${esc(e.message)}</p>`);}}
 function checkpoint(test=false){localStorage.setItem(test?keys.checkpoint+'-test':keys.checkpoint,getPayload());notify(test?'Test starting point saved.':'Debug checkpoint saved.');}
 function launch(type){perform(()=>{if(type==='govern'&&!getState().laws.governorGeneral)throw Error('Enable Governor General in Laws & offices first.');checkpoint(true);const s=getState(),boundary=type==='parliament-menu'?'parliament':'operations';if((boundary==='operations'&&phaseFor(s))||(boundary==='parliament'&&phaseFor(s)?.status!=='complete')||s.gameEnd||s.parliamentFinishedTurn===s.turn)commit(debugPhase(s,boundary),'prepare '+boundary+' test');if(type==='deploy')deploy();else actions(type);});}
 function editRegion(){perform(()=>{
  const s=getState(),v=s.regions[selected];let ownership=v.control==='company'?'company':v.overlord?'vassal':'sovereign';
  const drawForm=()=>{
   const parents=IDS.filter(id=>id!==selected&&s.regions[id].control==='indian'&&!s.regions[id].overlord);
   form('Debug map · '+label(selected),`${pick('debug-edit-region','Region to edit',regions,selected)}<p>Setup edit only. Conquests and unrest effects are tested through the action buttons. Home regions can only be assigned to their own Presidency. Empire capitals are derived from their subjects.</p>${pick('debug-control','Control',[['sovereign','Indian sovereign / capital'],['vassal','Indian empire subject'],['company','Company']],ownership)}<div id="debug-owner">${ownership==='company'?pick('debug-presidency','Presidency',PRESIDENCIES.map(id=>[id,label(id),PRESIDENCIES.includes(selected)&&id!==selected]),PRESIDENCIES.includes(selected)?selected:v.presidency||'bombay'):ownership==='vassal'?pick('debug-overlord','Empire capital',parents.map(id=>[id,label(id)]),v.overlord||parents[0]):''}</div>${ownership!=='company'?number('debug-tower','Tower levels',v.strength):number('debug-unrest','Unrest cubes',v.unrest,0,30)}<h4>Orders</h4>${REGIONS[selected].orders.map(([id,,,value])=>`<label class="check-label"><input type="checkbox" data-debug-order="${id}" ${v.orders[id]?'checked':''}>${esc(orderLabel(id))} · open</label>`).join('')}${ownership!=='company'?`<label class="check-label"><input id="debug-loot" type="checkbox" ${v.lootAvailable?'checked':''}>Unclaimed loot token</label>`:'<p>Company control uses zero tower strength and a spent loot token.</p>'}<p class="small-note">If a capital becomes a subject or Company territory, its subjects become sovereign. The Elephant is adjusted to a legal position if this edit invalidates its current placement.</p>`,'Apply setup',()=>{
    const orders=Object.fromEntries([...document.querySelectorAll('[data-debug-order]')].map(n=>[n.dataset.debugOrder,n.checked]));
    const patch={control:ownership==='company'?'company':'indian',presidency:ownership==='company'?$('debug-presidency').value:null,overlord:ownership==='vassal'?$('debug-overlord')?.value:null,strength:ownership==='company'?0:Number($('debug-tower').value),unrest:ownership==='company'?Number($('debug-unrest').value):0,lootAvailable:ownership==='company'?false:$('debug-loot').checked,orders};
    if(ownership==='vassal'&&!patch.overlord)throw Error('No eligible independent capital exists.');
    commit(debugEditRegion(s,selected,patch),'edit '+label(selected));$('dialog').close();
   });
   $('debug-edit-region').onchange=()=>{selected=$('debug-edit-region').value;selectRegion?.(selected);editRegion();};
   $('debug-control').onchange=()=>{ownership=$('debug-control').value;drawForm();};
  };drawForm();
 });}
 function elephant(){perform(()=>{const s=getState(),positions=legalElephants(s);form('Debug map · Elephant',`${pick('debug-position','Legal Elephant placement',positions.map((p,i)=>[String(i),p.to?`${label(p.from)} → ${label(p.to)}`:`Inside ${label(p.from)}`]),String(positions.findIndex(p=>p.from===s.elephant.from&&p.to===s.elephant.to)))}<p>Company regions allow inside placement; subjects face their capital; sovereigns face an eligible neighbour. Fully surrounded capitals use the subject-to-capital redirect.</p>`,'Place Elephant',()=>{const p=positions[Number($('debug-position').value)];commit(debugEditElephant(s,p.from,p.to),'place Elephant');$('dialog').close();});});}
 function flags(){perform(()=>{const s=getState();form('Debug · laws and offices',`<p>Toggle setup conditions without simulating Parliament. Use Test Parliament to resolve actual passed/failed effects. Only offices whose existence the regular app tracks are represented here.</p>${Object.entries(LAW_NAMES).map(([id,name])=>`<label class="check-label"><input type="checkbox" data-debug-law="${id}" ${s.laws[id]?'checked':''}>${esc(name)}</label>`).join('')}<label class="check-label"><input type="checkbox" id="debug-china" ${s.chinaOffice?'checked':''}>China office created</label><p class="small-note">Governor General replaces the regional Governors and Director of Trade. Envoy to China requires the China office. Calico Acts, Military Oversight and Royal Protection include table-only effects. Untracked office vacancies and Army pieces remain reported through the normal dialogs.</p>`,'Apply conditions',()=>{const laws=Object.fromEntries([...document.querySelectorAll('[data-debug-law]')].map(n=>[n.dataset.debugLaw,n.checked]));commit(debugFlags(s,laws,$('debug-china').checked),'laws and offices');$('dialog').close();});});}
 function phase(){perform(()=>{const s=getState();form('Debug · phase and turn',`${pick('debug-phase','Test boundary',[['operations','Company operations'],['events','Events in India · ready to draw'],['parliament','Parliament · India complete'],['refresh','Upkeep · Parliament complete']],'operations')}${number('debug-turn','Board turn',s.turn,SCENARIOS[s.scenario].start,SCENARIOS[s.scenario].end)}<p>This stages a phase boundary, without resolving skipped phases or refreshing physical troops. It preserves the map and action history.</p>`,'Stage phase',()=>{const n=clone(s);n.turn=Number($('debug-turn').value);commit(debugPhase(n,$('debug-phase').value),'phase / turn');$('dialog').close();});});}
 function event(){perform(()=>{const s=getState();form('Debug · choose an event test',`${pick('debug-tile','Event tile',Object.keys(TILES).map(id=>[id,tileLabel(id)]),s.eventStack.draw[0])}${pick('debug-top','Newly exposed region',regions,exposedRegion(s.eventStack))}<details><summary>Repeatable invasion dice (debug only)</summary>${pick('debug-storm','Invasion storm die',[['random','Roll normally'],...STORM_FACES.slice(0,5).map((f,i)=>[String(i),f.label])],'random')}${number('debug-invasion','Fixed invasion d6 · 0 means roll normally',0,0,6)}<p>Overrides apply only to this Foreign Invasion test. All defence, rout and aftermath rules still use the shared engine.</p></details><p>The chosen tile is staged on top of the real test deck, then drawn and fully resolved. It is consumed by the test, including Shuffle, March and the new exposed-region page. A starting checkpoint is saved automatically.</p>`,'Stage & resolve tile',()=>{
    const tile=$('debug-tile').value,region=$('debug-top').value,storm=$('debug-storm').value,die=Number($('debug-invasion').value);
    if(!Number.isInteger(die)||die<0||die>6)throw Error('Choose an invasion die from 0 to 6.');
    const next=debugStageEvent(s,tile,region);checkpoint(true);commit(next,'stage '+tileLabel(tile));$('dialog').close();draw({...(TILES[tile].event==='foreign'&&storm!=='random'?{stormFace:Number(storm),storm:STORM_RESULTS[Number(storm)]}:{}),...(TILES[tile].event==='foreign'&&die?{rolls:Object.fromEntries(IDS.map(id=>[id,die]))}:{})});
   });});}
 function deck(){perform(()=>{
  const s=getState();let tile=s.eventStack.draw[0],destination='draw',index=0;
  const render=()=>{
   const current=getState().eventStack,pile=current[destination],max=pile.filter(id=>id!==tile).length;
   form('Debug · event deck',`<p>All 20 unique tiles must remain present. Draw position 1 is the next tile. Discard position 1 is the oldest tile; the newest is last. The Shuffle tile must remain in the draw pile, and that pile cannot be empty.</p>${pick('debug-deck-tile','Tile to move',Object.keys(TILES).map(id=>[id,tileLabel(id)]),tile)}${pick('debug-pile','Destination pile',[['draw','Draw pile'],['discard','Discard pile']],destination)}${number('debug-index',destination==='draw'?'Position · 1 is next':'Position · 1 is oldest',Math.min(index,max)+1,1,max+1)}<div class="debug-deck-grid">${['draw','discard'].map(key=>`<section><h4>${key==='draw'?'Draw · next first':'Discard · oldest first'}</h4><ol>${current[key].map(id=>`<li>${esc(tileLabel(id))}</li>`).join('')||'<li>Empty</li>'}</ol></section>`).join('')}</div><div class="choice-buttons"><button id="debug-shuffle-draw">Shuffle draw</button><button id="debug-collect-deck">Collect & shuffle all</button></div>`,'Move tile',()=>{tile=$('debug-deck-tile').value;destination=$('debug-pile').value;index=Number($('debug-index').value)-1;commit(debugMoveTile(getState(),tile,destination,index),'move deck tile');render();});
   $('debug-deck-tile').onchange=()=>{tile=$('debug-deck-tile').value;index=0;render();};$('debug-pile').onchange=()=>{destination=$('debug-pile').value;index=0;render();};
   $('debug-shuffle-draw').onclick=()=>{try{const x=getState();commit(debugDeck(x,shuffled(x.eventStack.draw),x.eventStack.discard),'shuffle draw pile');render();}catch(e){fail(e);}};
   $('debug-collect-deck').onclick=()=>{try{const x=getState();commit(debugDeck(x,shuffled(Object.keys(TILES)),[]),'collect / shuffle all tiles');render();}catch(e){fail(e);}};
  };render();
 });}
 function reset(){perform(()=>{const s=getState();form('Debug · reset or quick setup',`${pick('debug-scenario','Scenario starting point',Object.entries(SCENARIOS).map(([id,c])=>[id,c.label+' · '+c.name]),s.scenario)}${pick('debug-preset','Setup',[['scenario','Exact scenario map'],['company','Company home regions · two unrest each'],['open','Scenario · all orders open'],['closed','Scenario · all orders closed']],'scenario')}<p>Replaces only this debug workspace, resets test history and phase, and creates a fresh event stack. Undo can restore the prior setup.</p>`,'Reset debug map',()=>{
    let n=debugState($('debug-scenario').value);const preset=$('debug-preset').value;
    if(preset==='company')for(const id of PRESIDENCIES)n=debugEditRegion(n,id,{control:'company',presidency:id,unrest:2});
    if(['open','closed'].includes(preset))for(const r of Object.values(n.regions))for(const id of Object.keys(r.orders))r.orders[id]=preset==='open';
    commit(n,'reset '+$('debug-scenario').value+' / '+preset);$('dialog').close();
   });});}
 function quickDraw(){perform(()=>{checkpoint(true);const s=getState();if(phaseFor(s)?.status!=='events'||s.indiaPhase.completed===s.indiaPhase.total)commit(debugPhase(s,'events'),'prepare event draw');draw();});}
 function clearReports(){perform(()=>{form('Debug · clear current-turn reports','<p>Clear this turn’s reports and action limits, including Tax counts, Govern success, Commander catastrophes and the region-loss counter. Keep the map, laws and deck unchanged. Undo can restore them.</p>','Clear reports',()=>{const n=clone(getState());n.history=n.history.filter(h=>h.turn!==n.turn);commit(n,'clear current-turn reports');$('dialog').close();});});}
 function restorePoint(key){try{const raw=localStorage.getItem(key);if(!raw)throw Error('No starting point has been saved yet.');restore(raw);notify('Debug starting point restored.');}catch(e){fail(e);}}
 function render(id){selected=id;const pending=hasPending()||getState().eventStack?.pending;
  $('debug-controls').innerHTML=`<div class="debug-heading"><div><p class="eyebrow">DEBUG WORKSPACE · SEPARATE AUTOSAVE</p><h3>India test bench</h3><p>Setup edits build a position. Test actions use the regular rules, dialogs and event engine.</p></div><a class="document-link" href="index.html">Return to regular game ↗</a></div><details id="debug-control-details" ${controlsOpen?'open':''}><summary>Setup and test controls</summary>${pending?'<p class="notice">A test is pending. Resume it, or restore its starting point before editing the setup.</p>':''}<div class="debug-toolbar"><button id="debug-edit" ${pending?'disabled':''}>Edit ${label(selected)}</button><button id="debug-elephant" ${pending?'disabled':''}>Place Elephant</button><button id="debug-flags" ${pending?'disabled':''}>Laws & offices</button><button id="debug-phase-button" ${pending?'disabled':''}>Phase & turn</button><button id="debug-deck" ${pending?'disabled':''}>Edit event deck</button><button id="debug-reset" ${pending?'disabled':''}>Scenario reset / presets</button></div><div class="debug-toolbar"><button id="debug-event" ${pending?'disabled':''}>Choose event test</button><button id="debug-draw">${pending?'Resume pending test':'Draw next tile'}</button><button id="debug-deploy" ${pending?'disabled':''}>Test Deploy</button><button id="debug-envoy" ${pending?'disabled':''}>Test Special Envoy</button><button id="debug-governor" ${pending?'disabled':''}>Test Governor actions</button><button id="debug-general" ${pending?'disabled':''}>Test Governor General</button><button id="debug-parliament" ${pending?'disabled':''}>Test Parliament / dilemmas</button><button id="debug-blackmail" ${pending?'disabled':''}>Test Blackmail</button></div><div class="debug-toolbar"><button id="debug-checkpoint">Save checkpoint</button><button id="debug-restore">Restore checkpoint</button><button id="debug-replay">Restore last test start</button><button id="debug-clear" ${pending?'disabled':''}>Clear turn reports / limits</button><button id="debug-copy" ${pending?'disabled':''}>Copy regular game into debug</button></div><p class="small-note">Use Undo for each setup/action. Saved games has separate debug snapshots and JSON backups. Army availability and player-held offices are reported in the same way as regular play.</p></details>`;
  $('debug-control-details').ontoggle=()=>{controlsOpen=$('debug-control-details').open;};
  const bind=(id,fn)=>$(id).onclick=fn;
  bind('debug-edit',editRegion);bind('debug-elephant',elephant);bind('debug-flags',flags);bind('debug-phase-button',phase);bind('debug-deck',deck);bind('debug-reset',reset);bind('debug-event',event);bind('debug-draw',()=>pending?actions():quickDraw());
  for(const [id,type] of [['deploy','deploy'],['envoy','envoy'],['governor','governor'],['general','govern'],['parliament','parliament-menu'],['blackmail','blackmail-menu']])bind('debug-'+id,()=>launch(type));
  bind('debug-checkpoint',()=>{try{checkpoint();}catch(e){fail(e);}});bind('debug-restore',()=>restorePoint(keys.checkpoint));bind('debug-replay',()=>restorePoint(keys.checkpoint+'-test'));bind('debug-clear',clearReports);
  bind('debug-copy',()=>perform(()=>{const raw=localStorage.getItem(workspaceKeys('/index.html').campaign);if(!raw)throw Error('No regular campaign has been saved in this browser.');const n=decode(raw).state;checkCopy(n);if(!n.eventStack)n.eventStack=createEventStack();n.debugMode=true;n.campaignName='Debug · '+n.campaignName.slice(0,65);commit(n,'copy regular campaign');}));
 }
 function checkCopy(n){if(n.eventStack?.pending)throw Error('Finish the regular campaign’s pending tile before copying its map.');validateDebugState(n);}
 return {render,editRegion};
}
